from pathlib import Path
import json,hashlib,datetime
O=Path(__file__).resolve().parent;C=Path('/tmp/medina-g21-source-cache');now=datetime.datetime.now(datetime.timezone.utc).isoformat();rows=[]
def add(id,url,publisher,file,version,section,passage,population,limits):
 p=Path(file) if str(file).startswith('/') else C/file
 rows.append(dict(id=id,url=url,publisher=publisher,cache_path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),version=version,section=section,passage=passage,passage_type='faithful_paraphrase',population=population,limits=limits,limitations=limits,read_at=now,reader='astra_nephrologie',production_name='Sol-Neurologie-G21',runtime_name='sol_nephrologie',reading_scope='selected_passages_actually_read_or_explicit_same_session_reuse'))
cim='https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686264/master';cp='/tmp/medina-n04-source-cache/CIM.raw'
add('CH-CIM',cim,'OFS, nomenclature suisse',cp,'CIM-10-GM 2024','G21 et G21.0/.1/.2/.3/.4/.8/.9','G21 syndrome parkinsonien secondaire ; G21.0 malin des neuroleptiques ; .1 autres médicamenteux ; .2 autres agents externes ; .3 post-encéphalitique ; .4 libellé Maladie de Parkinson vasculaire ; .8 autres ; .9 sans précision.','Nomenclature suisse','Le syndrome malin aigu est inclus, pas seulement un ralentissement chronique. Pour .0/.1/.2, code de cause externe supplémentaire au besoin ; aucun .5/.6/.7 inventé.')
add('CH-CIM-BOUND',cim,'OFS, nomenclature suisse',cp,'2024','G20, G22* et G23','G20 maladie de Parkinson, G22* syndrome au cours de maladies classées ailleurs avec inclusion syphilitique A52.1 ; G23 autres maladies dégénératives des noyaux gris centraux.','Nomenclature','Un syndrome clinique ne détermine pas seul un code. État ressemblant à SMN après sevrage dopaminergique ne signifie pas automatiquement G21.0 ; cause et documentation restent nécessaires.')
hug='https://www.hug.ch/sites/interhug/files/structures/medecine_de_premier_recours/parkinsonism_smpr_180418.pdf'
add('CH-HUG-SEMIO',hug,'HUG, Fleury et Jackson','CH-HUG2018.txt','17 avril 2018','Identifier un syndrome parkinsonien 1–3','Bradykinésie : lenteur et réduction de vitesse/amplitude aux mouvements répétés ; rigidité au mouvement passif lent avec sujet détendu ; tremblement observé au repos, en posture et en action.','Enseignement clinique au praticien','Document daté, pas directive suisse 2026. Vignettes originales du support non recopiées ; pas chiffres de prévalence déduits de graphiques non lus.')
add('CH-HUG-DIFF',hug,'HUG','CH-HUG2018.txt','2018','Investiguer 1–3 et imagerie','Reprendre médicaments y compris neuroleptiques cachés, début, symétrie, terrain vasculaire et signes non moteurs ; alertes atypiques : chutes précoces, dysautonomie, signes pyramidaux/cérébelleux/oculomoteurs ; imagerie selon question.','Syndrome parkinsonien, diagnostic différentiel','La partie thérapeutique du support vise surtout maladie de Parkinson et n’est pas transposée à tout G21. Affirmations anciennes de neuroprotection et tests génétiques non retenues.')
phel='https://www.phel.ch/upload/docs/application/pdf/2023-03/syndrome_nl_malin_aux_urgences_flb_23.02.2023.pdf'
def P(id,section,text,limit):add(id,phel,'PHEL/HRC-Rennaz, Ferdinand Le Bloc’h','CH-PHEL2026.txt','Mai 2026 écrit dans le document, malgré URL 2023',section,text,'Enseignement hospitalier local du syndrome malin',limit)
P('CH-PHEL-VERSION','Titre, conditions de diffusion et introduction','Support réellement mai 2026 ; urgence idiosyncratique avec troubles mentaux, rigidité, dysautonomie et thermorégulation ; antagonisme D2 ou sevrage dopaminergique comme contextes.','Enseignement informatif local, pas directive nationale. Métadonnées moteur 2023 non utilisées comme version. Paraphrases factuelles et métadonnées seulement, pas reproduction du support.')
P('CH-PHEL-CLIN','Présentation séquentielle, diagnostic et différentiels','Présentation hétérogène et progressive ; CK/myoglobine, rein, ions, température et conscience servent à rechercher complications. Pas de test spécifique ; infection, sérotoninergique et catatonie à discuter.','Ne pas attendre toute la tétrade ou un seuil de CK pour agir. Pourcentages et délais de vignette ne sont pas une épidémiologie suisse générale.')
P('CH-PHEL-CARE','Mesures immédiates et monitoring','Arrêt du neuroleptique causal en SMN ; si sevrage dopaminergique suspecté, question inverse de reprise urgente évaluée ; soutien ventilation, température, circulation, eau, rein et rhabdomyolyse.','Pas volume de remplissage ou cible de diurèse uniforme publié ; adapter organes et gravité. Ne pas arrêter aveuglément tous les antiparkinsoniens.')
P('CH-PHEL-LIMIT','Mesures pharmacologiques','Options hospitalières présentées : benzodiazépines, bromocriptine, dantrolène selon gravité ; anticholinergiques centraux peu utiles dans SMN et susceptibles d’aggraver hyperthermie.','Données souvent faibles ; indications/voies/formulations FI distinctes. Pas injection générique Agilus/Dantrium transposée, ni bipéridène automatique pour rigidité fébrile.')
P('CH-PHEL-RECHALL','Réintroduction antipsychotiques','Fenêtre proposée 5–14 jours, autre molécule, faible dose, titration lente, pas dépôt et surveillance rapprochée.','Cette fenêtre du support n’est pas un calendrier universel. Recommandation BAP au moins deux semaines après résolution attribuée séparément ; décision multidisciplinaire.')
add('CH-GENEVA','https://pubmed.ncbi.nlm.nih.gov/29661694/','Fleury, Brindel, Nicastro, Burkhard, Genève','CH-GENEVA2018-abstract.json','2018 ; DOI10.1016/j.parkreldis.2018.03.030','Résumé primaire obtenu via EuropePMC, objectifs/méthodes/résultats','Recherche dans hôpitaux, neurologues privés et EMS, diagnostics2003–2012 ;1235 patients vivants,80% dégénératifs et20% non dégénératifs. Parmi non dégénératifs,43,4% médicamenteux et37% vasculaires.','Étude descriptive populationnelle genevoise historique','Résumé seulement réellement lu, article complet sous abonnement non consulté. Pas incidence actuelle suisse G21, pas mêmes dénominateurs ; PMID29310988 est un autre article vasculaire, erreur de rapprochement corrigée avant rédaction.')
add('CH-PROFILES','https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','CIMS/SMIFK','/workspace/medina-source-cache/C85/profiles2017-official.pdf','2017','Examen neurologique, mouvements involontaires, marche/équilibre, SSP système nerveux','Examiner tonus, force, réflexes, mouvements involontaires, marche, équilibre et coordination ; raisonner devant tremblement, mouvements anormaux et trouble de marche.','Formation médicale suisse','Réutilisation explicite du même bloc, passages pertinents rouverts ; aucun item fédéral officiel intitulé G21 inventé.')
add('CH-MEBEKO','https://www.bag.admin.ch/dam/fr/sd-web/fL9EvX0YPT2d/20260204_Exigences%20MED%202026_f.pdf','OFSP/MEBEKO','/workspace/medina-source-cache/C85/mebeko2026.md','3 mars 2026','Introduction, examen CK et CS','L’examen fédéral2026 comprend connaissances cliniques et compétences pratiques ; les cas MEDINA restent originaux fictifs.','Examen2026','Document réutilisé et introduction rouverte ; empreinte du texte fournisseur, pas PDF original. Aucun quiz présenté comme question officielle.')
add('FI-AKI','https://amiko.oddb.org/fr/fi?gtin=7680240360220','FI suisse Akineton/-retard, Laboratorio Farmaceutico S.I.T.','FI-AKINETON.html','Mai 2022','Indications, doses/formes, organes, sécurité, reproduction, interactions, mécanisme','Comprimé2mg ; adulte Parkinson départ1mg deuxfois/j, augmentation2mg/j, maximum16mg/j. EPS médicamenteux :1–4mg1–4fois/j selon intensité. Retard4mg : titration avec2mg d’abord,1–2comprimés/j usuels,max3 ; ne pas diviser/croquer.','Parkinson/EPS selon indication ; enfant expérience limitée surtout dystonies médicamenteuses','Les doses FI ne sont pas départ universel au haut de fourchette. Prudence âgé/cognition ; glaucome angle étroit, sténose digestive,mégacôlon/iléus contre-indiqués. Pas expérience foie/rein ; grossesse prudence, allaitement déconseillé. Charge anticholinergique, alcool, dyskinésies tardives à vérifier ; SMN n’est pas une indication automatique.')
add('FI-SYM','https://amiko.oddb.org/fr/fi?gtin=7680318410383','FI suisse Symmetrel, Novartis Pharma Schweiz','FI-SYMMETREL.html','Février 2025','Indication adulte, doses, âge/rein, précautions, reproduction et mécanisme','Capsule100mg ; adulte syndrome parkinsonien dont médicamenteux :100mg/j4–7jours puis100mg deuxfois/j si toléré ; exception300mg/j sélectionnée. ≥65ans sans pathologie rénale : maximum recommandé100mg/j. IR : allonger intervalle selon ClCr de la FI,100mg toutes48h à clairance dans intervalle25–35 ; hémodialyse généralement100mg/semaine.','Indication parkinsonienne adulte, pas doses grippe enfant appliquées à G21','Début IR Parkinson100mg le premier jour, pas charge grippe200mg. Bornes partagées du tableau et unité de ClCr à vérifier, pas remplacement mécanique par DFGe. Confusion/psychose/épilepsie réfractaire et grossesse contre-indiquées ; soja/cacahuète aussi. Pas arrêt brutal, toxicité rénale, hallucinations/œdèmes/interactions ; contraception hautement efficace jusqu’à5jours après, pas allaitement. FI mécanisme dopaminergique hypothétique, pas agonisteD2 pur.')
add('FI-MAD','https://amiko.oddb.org/fr/fi?gtin=7680523770487','FI suisse Madopar, Roche Pharma Suisse','FI-MADOPAR-LIQ.html','Juin 2023','Formes, indication, posologie, organes, sécurité, reproduction et mécanisme','Levodopa/bensérazide4:1 ; LIQ62,5=50+12,5mg,LIQ125=100+25mg ; FI indique syndrome parkinsonien sauf origine médicamenteuse. Début précoce Parkinson par LIQ62,5 trois/quatrefois/j entre autres schémas ; entretien LIQ125 trois–sixfois/j individualisé. LIQ dans25–50mL eau, remuer et boire dans30min ; repas30min avant ou1h après.','Indication et forme précises, pas traitement universel de G21','Contre-indiqué<25ans, grossesse/contraception inadéquate, psychose et autres affections listées ; pas allaitement. ClCr>30mL/min légère/modérée : pas adaptation ; décompensations et foie à vérifier. Arrêt brutal peut donner état semblable SMN ; prise en charge urgente distincte. DR et standard/LIQ non interchangeables par simple masse,125mg ne signifie pas125mg de lévodopa.')
add('FI-PARL','https://amiko.oddb.org/fr/fi?gtin=7680390010204','FI suisse Parlodel, Sandoz Pharmaceuticals','FI-PARLODEL.html','Mai 2020','Indications, syndrome parkinsonien, organes, contre-indications, interactions et reproduction','Bromocriptine comprimé2,5mg, indication syndrome idiopathique/postencéphalitique. Début1,25mg/j lesoir première semaine, augmentation1,25mg/semaine répartie2–3prises ; éventuel palier2,5mg/semaine après6–8semaines,maximum30mg/j.','Indication parkinsonienne précise, pas dose SMN autorisée dans FI','SMN : usage spécialisé hors indication cité dans PHEL/BAP, ne pas fusionner avec dose Parkinson. CI troubles psychiques sévères,sepsis,antécédentAVC,atteinte vasculaire/coronarienne,HTA mal contrôlée,foie sévère et inhibiteurs CYP3A4 puissants/modérés. Prudence âgé et fibrose/valves ; grossesse arrêt sauf nécessité médicale, allaitement hors indication spécifique à éviter. CYP3A/CYP3A4 conservés sans séparation typographique.')
dgn='https://register.awmf.org/assets/guidelines/030-010l_Parkinson_Krankheit_2023-11_1.pdf'
add('EU-DGN-DEF',dgn,'DGN, Höglinger/Trenkwalder et al.','EU-DGN2023.txt','Version8.1,25octobre2023 ; correction26novembre2023 ; validité annoncée24octobre2028','Définitions p24–25, syndromes secondaires','Bradykinésie, rigidité indépendante vitesse et tremblement de repos ; tremblement pas obligatoire. Secondaire : cause identifiable non génétique, notamment médicaments,lésions vasculaires,toxiques,métaboliques ou encéphalitiques.','Adulte, cadre diagnostique de maladie de Parkinson et différentiels','Le cadre de syndrome n’impose pas G21 à toutes causes ni une prescription de Parkinson. Roue dentée sans résistance ne suffit pas à définir rigidité ; instabilité posturale non requise comme signe cardinal initial de Parkinson.')
add('EU-DGN-IMG',dgn,'DGN','EU-DGN2023.txt','2023,version8.1','Synthèse recommandations d’imagerie et diagnostique','IRM cérébrale précoce pour diagnostic différentiel ; DAT-SPECT en syndrome Parkinson/tremblement cliniquement incertain si résultat a une conséquence clinique, pour déficit nigrostriatal.','Question diagnostique adulte','Pas scanner systématique de SMN ni preuve qu’un DAT anormal identifie seul maladie de Parkinson idiopathique ; clinique, autres dégénérescences et médicaments interférents évalués avec spécialistes.')
add('EU-DGN-SCOPE','https://register.awmf.org/de/leitlinien/detail/030-010','Registre AWMF/DGN, extrait primaire indexé','EU-DGN-REGISTER-excerpts.txt','Version8.1 du25octobre2023 ; mise en ligne des documents actualisés30novembre2023','Population et exclusions, extrait public reçu/lus','La directive vise des adultes avec maladie de Parkinson ; diagnostic/traitement des syndromes secondaires ne font pas partie de son périmètre thérapeutique, diagnostic différentiel discuté.','Registre de directive','Extrait indexé réellement lu, page applicative ouverte sans lignes lisibles ; pas lecture intégrale du registre. Utilisation limitée à portée/version, pas directive de traitement universel G21.')
bap='https://pmc.ncbi.nlm.nih.gov/articles/PMC10101189/'
def B(id,section,text,limit):add(id,bap,'British Association for Psychopharmacology, Rogers et al., groupe international','EU-BAP2023.html','11avril2023 ; J Psychopharmacol37:327–369 ; DOI10.1177/02698811231158232',section,text,'Consensus britannique avec auteurs internationaux, SMN/catatonie',limit)
B('EU-BAP-CLIN','Section Neuroleptic malignant syndrome','Tableau peut associer confusion/catatonie, rigidité, hyperthermie et dysautonomie ; présentation atypique avec peu/pas de fièvre ou rigidité possible. CK et leucocytose non spécifiques ; catatonie maligne et causes médicales différentielles.','Pas test unique ni tétrade obligatoire avant urgence. Les fréquences historiques ne deviennent pas incidence suisse actuelle G21.')
B('EU-BAP-THERAPY','Recommandations NMS','Arrêter antagonistes dopaminergiques et anticholinergiques ; soutien voies aériennes, ventilation,température,déglutition,équilibre hydrique ; surveiller K,rein,rhabdomyolyse,aspiration et thromboses. Options selon gravité : lorazépam,bromocriptine/amantadine,dantrolène ou ECT spécialisés.','Recommandations souventC ou consensusS ; pas protocole universel de toute rigidité. Pas de doses injectables/ECT fabriquées ou de traitement causal sans diagnostic.')
B('EU-BAP-RECHALL','Recommandation finale et discussion de réintroduction','Différer reprise antipsychotique au moins deux semaines après résolution d’un SMN ; nécessité clinique,faible dose,titration prudente,surveillance et réduction autres risques.','Délai attribué à BAP, pas délai juridique suisse ni équivalence avec5–14jours du support PHEL ; reprise individualisée avec psychiatre.')
B('EU-BAP-LIMIT','Discussion des études et options NMS','Absence de RCT et hétérogénéité ; séries/cas et biais de publication limitent comparaison. Aucune molécule fiable dans tous les cas ; soutien et arrêt causal restent essentiels.','Pas efficacité universelle promise, pas assimilation catatonie/SMN/sérotoninergique. Association britannique à auteurs internationaux explicitement signalée, pas recommandation nationale américaine comme fondement.')
dip='https://pmc.ncbi.nlm.nih.gov/articles/PMC3325428/'
def D(id,section,text,limit):add(id,dip,'Shin et Chung, J Clin Neurol, revue coréenne','INT-DIP2012.html','2012 ; Drug-Induced Parkinsonism',section,text,'Revue internationale des parkinsonismes médicamenteux',limit)
D('INT-DIP-MECH','Pathophysiology','Blocage postsynaptiqueD2 striatal modifie la boucle indirecte GABAergique et la sortie pallido-nigrale vers thalamus ; modèle de réseau, différent d’une perte présynaptique nécessaire de neurones.','Modèle simplifié et revue ancienne ; pas tous médicaments même mécanisme, ni seuil universel de80% de perte neuronale/receptoroccupancy recopié. Figures de revue non importées.')
D('INT-DIP-CLIN','Clinical characteristics','Bilateralité/symétrie fréquentes mais asymétrie et tremblement de repos possibles ; dyskinésies bucco-linguo-faciales peuvent coexister. La clinique seule ne sépare pas toujours effet médicamenteux et Parkinson dévoilé.','Pas pourcentage de revue transformé en risque suisse actuel ; une asymétrie n’exclut pas une cause médicamenteuse.')
D('INT-DIP-TEST','Diagnosis and role of DAT imaging','Chronologie médicament, absence de syndrome antérieur et début sous exposition soutiennent le diagnostic. DAT présynaptique peut rester normal dans forme purement postsynaptique ; déficit suggère maladie/atteinte présynaptique concomitante.','Pas test obligatoire de toute exposition, pas maladie de Parkinson idiopathique prouvée par DAT seul ; sensibilité/spécificité exactes non garanties et suivi nécessaire.')
D('INT-DIP-MGMT','Treatments and outcomes','Réduire/retirer cause si possible, substitution coordonnée si besoin psychiatrique ; symptômes souvent régressent sur semaines/mois mais persistance,progression ou réapparition peuvent signaler un autre mécanisme.','Ni arrêt psychiatrique brutal universel ni attente imposée six mois avant aide ; absence de preuves de haute qualité pour nombreux traitements symptomatiques empiriques.')
D('INT-DIP-LIMIT','Discussion/conclusions et traitements','Distinguer licence d’un produit, bénéfice individuel et qualité de preuves. Le suivi peut rouvrir diagnostic malgré amélioration après retrait.','Pas garantie de guérison complète ou délai fixe ; classifications anciennes de molécules et explications récepteur simplifiées non importées sans contrôle FI.')
vas='https://pmc.ncbi.nlm.nih.gov/articles/PMC5857227/'
def V(id,section,text,limit):add(id,vas,'Rektor et al., groupe expert international à direction européenne','INT-VASCULAR2018.html','2018 ; DOI10.1016/j.parkreldis.2017.12.030 ; PMID29310988',section,text,'Consensus expert sur phénotypes vasculaires',limit)
V('INT-VASC-CLASS','Résumé, prémabule et sous-types','Trois cadres : début aigu/subaigu postAVC, début insidieux prédominant marche/axe avec signes associés, et formes mixtes neurodégénératives/vasculaires. Concordance clinique,anatomique et imagerie nécessaire.','Définitions hétérogènes et consensus ; G21.4 n’est pas tout trouble de marche avec facteurs vasculaires.')
V('INT-VASC-MRI','Imagerie, pathologie et différentiels','Lésions de substance blanche fréquentes chez sujets âgés asymptomatiques ; cause vasculaire non prouvée par hypersignal isolé. Myélopathie,hydrocéphalie,lésion frontale et dégénérescence restent différentiels.','Pas causalité déduite de l’IRM seule ni biopsie routine ; pathologies mixtes fréquentes et données clinico-pathologiques limitées.')
V('INT-VASC-RESPONSE','DAT, tableau2 et discussion','Atteinte focale nigrostriatale postAVC peut répondre au dopaminergique ; forme insidieuse souvent moins sensible. DAT et localisation peuvent aider à sélectionner avis/essai clinique.','Pas absence de réponse absolue de tout G21.4, ni dosage universel ou bénéfice garanti ; prévention vasculaire suit la maladie réelle, pas antiagrégant automatique sur G21.')
add('NORMAL-TISSUE','https://openstax.org/books/anatomy-and-physiology-2e/pages/12-2-nervous-tissue','OpenStax, science normale','/tmp/medina-g09-source-cache/NORMAL-TISSUE.txt','Anatomy and Physiology2e,2022','Neurones,astrocytes,microglie,oligodendrocytes','Neurones et glie ont rôles distincts ; astrocytes contribuent environnement/barrière, microglie surveillance/phagocytose, oligodendrocytes myéline. Pigment H&E ne mesure pas transmission dopaminergique.','Tissu humain normal, réutilisation même bloc rouverte','Manuel américain utilisé seulement pour faits normaux paraphrasés ; aucune recommandation clinique américaine comme fondement, aucune figure importée. Pas CNS absolument fermé à toute immunité.')
for id,file,url,text,limit in [
 ('IMG-BASAL','figure-basal.html','https://commons.wikimedia.org/wiki/File:Basal-ganglia-coronal-sections.png','Andrew Gillies, création humaine publiée3mars2005 ; modèle de coupes coronales du cerveau humain et noyaux gris, CC BY-SA3.0 ; original réellement vu.','Schéma normal, pas IRM ni lésion, pas flèches thérapeutiques générées ; abréviations de l’original explicitées.'),
 ('IMG-STRIATUM','figure-gray718.html','https://commons.wikimedia.org/wiki/File:Gray718.png','Gray/Carter, Anatomy of the Human Body1918, planche718 ; noyaux caudé,lenticulaire,capsule interne,thalamus sur original réellement vu ; scan domaine public.','Page sans description anatomique détaillée ; identification liée aux étiquettes originales et livre humain. Pas orientation/diagnostic/patient inventés ni datation avant1858 adoptée.'),
 ('IMG-MOTOR','figure-motor.html','https://commons.wikimedia.org/wiki/File:Gray764.png','Gray1918 planche764, trajet moteur modifié de Poirier, humain explicite ; scan domaine public, original revu dans ce cours.','Anatomie normale pyramidal versus régulation extrapyramidale ; pas lésion G21 ni mesure de rigidité.'),
 ('IMG-HISTO','figure-neuromelanin.html','https://commons.wikimedia.org/wiki/File:Neuromelanin_in_a_neuron_of_the_substantia_nigra.jpg','Tulemo, propre microphotographie humaine H&E24janvier2021 ; neuromélanine brune, barre20µm, CC BY-SA4.0, original réellement vu.','Statut clinique non précisé ; pas cerveau certifié sain, pas corps de Lewy, dosage dopamine ou récepteurD2 inférés de ce pigment.'),
 ('IMG-GOWERS','figure-gowers.html','https://commons.wikimedia.org/wiki/File:Sir_William_Richard_Gowers_Parkinson_Disease_sketch_1886.jpg','William Richard Gowers, dessin1886, A Manual of Diseases of the Nervous System, attribution explicite dans page source et domaine public ; original réellement vu.','Référence historique de maladie de Parkinson, pas cas de G21 prouvé ni prototype universel ; posture statique ne prouve pas festination/vitesse. PDF savant UCL403 non lu, pas contourné.')]:
 add(id,url,'Wikimedia Commons, provenance propre à l’original',file,'Versions historiques/institutionnelles explicites ; consultation2novembre2026','Description,origine,licence et original',text,'Originaux humains et auteurs humains vérifiés',limit)
assert len(rows)==37,len(rows)
(O/'source-ledger.json').write_text(json.dumps(dict(code='G21',production_name='Sol-Neurologie-G21',recorded_at=now,sources=rows,medical_human_validation=False,clinical_certification=False,limitations=['37lectures ciblées/réutilisations/provenances, pas37documents intégralement lus.','Quatre FI suisses réellement lues par sections ; usages et formes explicitement distincts.','Textes complets hors Git, métadonnées et paraphrases seulement ; accès exclus dans research-access-limits.json.']),ensure_ascii=False,indent=2)+'\n')
r=O/'research_G21';r.mkdir(exist_ok=True);m={x['id']:'S'+str(i) for i,x in enumerate(rows,1)}
